WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (721::BIGINT, 'No toma en cuenta la opinión de los estudiantes, si se equivoca en algún ejercicio o explicación no lo reconoce. Explica de forma muy confusa y poco clara, se enreda ella sola y no hace la clase de una forma participativa o que atraiga la atención de los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'ca4e5c5ad02ccf1fa1f0e719936debb7f73ce7346532ed242c6ac150516700b4'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Buena profe, es clara cuando explica. Califica fuerte los informes, si es que uno no sigue bien las instrucciones. Pero es muy buena persona, y tiene buena disposición'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'bfce31dc2a59d6c489c4687f6102baadf1012bfd4d30221f3fefd6f82f2ff8a7'::TEXT, ARRAY[613]::BIGINT[]),
    (721::BIGINT, 'Se nota que es buena en su profesión pero como profesora tiene ciertas carencias. Los exámenes son difíciles y las clases aburridas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '25f1c7b84e56b5c0d96f8fac0af21ae8e6b5cd02657f9c9900548ddbbc426ff1'::TEXT, ARRAY[3186, 3187]::BIGINT[]),
    (721::BIGINT, 'Si fuera presencial le hubiera entendido todo. Cuesta ponerle atención y entenderle en la virtualidad. Deja siempre quiz o quices después de cada clase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos exámenes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4598f41f09c9b5772321a136ff204976790583d323d49af1cd97db8e4f372538'::TEXT, ARRAY[568]::BIGINT[]),
    (721::BIGINT, 'En virtual explica rápido, sin embargo, siempre graba las clases y si usted se concentra entiende todo, da mucho material de apoyo super útil que no da la cátedra, a veces hace muchos quices , puede ser que le ayude si le falta muy poco para aprobar y nota que te esforzaste, es buena profe'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, 'a88adddd4cbd4ab3d30de87206d87a506126a11f33105c30ee8c3068e2d39147'::TEXT, ARRAY[568]::BIGINT[]),
    (721::BIGINT, 'Excelente profe, ayuda bastante en consulta'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '20ffcd1f347606f1ece2fd8347fc0a7b8a40a530252296751d06bb63470c3fe8'::TEXT, ARRAY[613]::BIGINT[]),
    (721::BIGINT, 'Es un amor, súper recomendada, no califica duro y deja tareas con folleto para las que se dispone a ayudarte en consulta. Contesta siempre el teléfono para consulta, ni es necesario ir a su oficina. Muy buena gente y atenta, le interesa que usted entienda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '8aab5378b1c28c4891a06ff108d72286b857da9c1cc3ea8751c2f1a6386ba562'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Es buena gente, se interesa mucho por el estudiante, explica bien y hace mucha práctica. Hace mucha práctica y quices muy parecidos al examen. Si hay que llevar buenas bases de química, pero es una profe que si le pides ayuda te la da.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'c2edcc0beb572358479ccf891a87244055536d7024d3465065281edcfe81d631'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'La profe es súper buena, deja prácticas que ayudan muchísimo para el examen. Es muy buena nota y explica bastante bien. Si uno no entiende algo en consulta ayuda full también. Recomendación en general para el curso, lean el libro, hace todo más fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7b012dbcc8b5ceb4fd7b6953109fcb983baf527adbb666a7e284824c11e61e08'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Es super buena gente y en serio quiere que uno aprenda.Explica muy bien,hace prácticas para el exámen que ayudan un montón.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'bfd59082db03deb884bfc575de13d5dec13d40caa4e893b0faad291e2b281521'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Como persona es muy pura vida, además se nota que sabe mucho, pero como profesora la verdad es decepcionante. Las clases que da son en general aburridas, el típico profe que se pone al frente con una presentación de power point y se hecha una hablada que nadie entiende bien.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5dd1e165f045607aa6422e137cd8e0f6840bdc8432e46c572c7b0f24fca011cf'::TEXT, ARRAY[3200, 3201, 3202]::BIGINT[]),
    (721::BIGINT, 'Explica muy bien, hay que estudiar para los quices, al principio intenta parecer ruda pero conforme avanza el semestre se le quita'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, '0b883957257e492b0ceef956a58fa19fa5bbd286a5285bb9a7433c009c993e57'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'No se siente que prepare las clases, muchas veces se enreda explicando. No le gusta que falten aunque sea asistencia libre. Cuenta el trabajo en clase de vez en cuando y pone ejercicios del libro en tareas o quices.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '10aa0cd38075ba2a2abfdb6bc6fbb67ab504b1344657f11a4918c37da302a1f7'::TEXT, ARRAY[3186, 3187]::BIGINT[]),
    (721::BIGINT, 'Los quices son muy fáciles y los hace todas las semanas lo que ayuda mucho en la nota final. Es muy directa para hablar pero se aprende bastante. Se preocupa porque uno aprenda de verdad.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c618bd2480616a25974010a0efa404600bd971e6a17a0fb63bd1ab76b6e3e52b'::TEXT, ARRAY[568]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'a73802fac55eeded966cf4ddee08bdcb9ffe0019b3e052bff2a5d0db58f4991c'::TEXT, ARRAY[3186, 3187]::BIGINT[]),
    (721::BIGINT, 'Sin duda de las mejores profesoras que tiene el TEC, es una haz, sin duda si tuviera que meter otro curso lo metería con ella. Es lo máximo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd03aafb41f3061a1f50e7285e389c61523bbef02f65e1b45463b5f20034c28df'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2016-09-23T00:00:00+00:00'::TIMESTAMPTZ, '8ea7cb8ba5ceb0fcd22fea0088c1f319fac759578bd2e211dc133f69e8c80811'::TEXT, ARRAY[3186, 3187]::BIGINT[]),
    (721::BIGINT, 'DEMASIADO BUENA, UNA PROFE QUE ENSEÑA DE VERDAD. NO DUDE METER CON ELLA'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '1ec5b1ca9ec1a9995000dab8a79225052b834d2f7e2f81363453691507e299f2'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Creo que es una de las peores profesoras que he tenido en el TEC. El curso es muy complicado y ella no sabe nada, no ayuda en nada, califica feo y tiene una pésima actitud hacia los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '42a066c8047b358498405eaa6c93e6b09dbc5a3de2c399dc533e885282d6b339'::TEXT, ARRAY[3186, 3187]::BIGINT[]),
    (721::BIGINT, 'Excelente profesora y persona.Hace todo lo posible para ayudar, con ella se aprende bastante y lo prepara de muy buena para los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, '4923dca50ae655b24e19fca2e15eb3c7fff115eb1d70ded27acd21f96f8157b9'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Explica muy bien. Hace muchos quices y al final elimina bastantes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '0414cf9170e0c38a983f78bb4e0ceb11097e9859a65cfb18602621ce5500f32a'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Es un amor de profesora. Se preocupa y le interesa que la clase entienda. Es excelente explicando! con ella se puede pasar quimica muy bien. El unico defecto es que hace demasiados quices pero igual tambien elimina muchos..'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '422a126ab5870dd350a5d68fba6e2b447ffa0d5cefb7e314c38fdcf226588f5f'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'af9d4836d27c7df8f79c09d910247ac35106b739e837220e6045742ee72500c3'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'f36f3daecb50dd6f43fe05dfb00ebae1f65ccc764baf6b2eeb25ccccd2d6c115'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Una profesora bastante buena, explica muy bien, buena gente, hace bastantes quices lo cuál es bueno porque lo obliga a uno a llevar la materia al día y de éstos elimina los más malos, le gusta que uno vaya a consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-17T00:00:00+00:00'::TIMESTAMPTZ, '84e5ec07d39cb190eecc81d82ca6940591d4892cd5c7be510fe6b6222652c1b6'::TEXT, ARRAY[568]::BIGINT[]),
    (721::BIGINT, 'Excelente en todos los sentidos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '456a08f18108147aed6e5ee9b945d92bdac001b85980a22ee18beb2d1c5b03b3'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Explica excelente. Busca que el estudiante se preocupe. Eso de los quices es una excelente acción por parte de ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'bc506f3908ee3ce5f7298fe7248a372fb9f4c8092cf7f4d9deccf6555b3daeb7'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Le pongo un 10 en facilidad porque explica tan bien que parece materia de kinder. Siempre hay que estudiar, hace 21 quizes y quita 7. Increiblemente paciente, se detiene cada 5 segundos a preguntar si van entendiendo y no le importa volver a explicar de 0. Muy buena gente, ayuda si uno le puso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'df272de2a138633ab31c6d93466d5c8ecf7fd66a68c4b20f1ffceb2ace628165'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Muy buena profe. Explica muy bien y se preocupa mucho por que uno entienda.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f6453eb2f6adb212daec96528446a38a0c868ae26ba7d5ea83b4a87ce91e197a'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '6e3c4c0616bdf4df16c5dc8089d214b34551e55e18869cccca695c546b9be10c'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'efc75d0e6ad01a00bab16e5fd7039bb6f6ce46e8019e51a5b91ad130556e610e'::TEXT, ARRAY[614]::BIGINT[]),
    (721::BIGINT, 'Super recomendado de los pocos profesores que de vdd se preocupan por el aprendizaje de los estudiantes. Si ella ve que le pone al final da puntos!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'd71569ab6a0d26e91793f315c2866d0774941861d3d50e4ebc2505e2a7ea82d8'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Muy pero muy buena profe, usa métodos diferentes a los demás para que uno entienda mejor, atiende TODA duda, es buena gente y vacilona...Hace unos 25 quices pero elimina los más malos. 100 por ciento recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a8833046dd28341d57886a6b797390a4bc792d797c1c4dff6fe973dc67073d35'::TEXT, ARRAY[613, 614]::BIGINT[]),
    (721::BIGINT, 'Muy buena gente, explica de forma bastante clara, realiza un quiz por semana y al final de semestre elimina los más malos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '7517ba82c2563f889e1b20738a763278ca31721bdeb5525b5f12e4159378ad4f'::TEXT, ARRAY[568]::BIGINT[]),
    (721::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'dedc181610652854665f13ca3aeb68dfa30c8dcb8f63f03f878dbb398da12f44'::TEXT, ARRAY[614]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
